"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[37],{9223(e){e.exports=JSON.parse('{"tag":{"label":"Exercises","permalink":"/concepts/tags/exercises","allTagsPath":"/concepts/tags","count":10,"items":[{"id":"backtracking/exercises","title":"Exercises: Backtracking","description":"These exercises review the two lessons on backtracking. They are different from the seminar activities (paths, Hamiltonian cycles and the traveling salesman) and from the lab problems, which are left for those sessions. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/backtracking/exercises"},{"id":"branch-and-bound/exercises","title":"Exercises: Branch and Bound","description":"These exercises review the two lessons on branch and bound. They are different from the seminar activities and from the lab problems, which are left for those sessions. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/branch-and-bound/exercises"},{"id":"brute-force/exercises","title":"Exercises: Brute Force","description":"These exercises review the lesson on brute force and exhaustive search. Most of them ask the same two questions the solutions are grouped at the end of the page.","permalink":"/concepts/brute-force/exercises"},{"id":"divide-and-conquer/exercises","title":"Exercises: Divide and Conquer","description":"These exercises review the lessons of the chapter, from the divide and conquer scheme to majority, mode and median. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/divide-and-conquer/exercises"},{"id":"dynamic-programming/exercises","title":"Exercises: Dynamic Programming","description":"These exercises review the two lessons on dynamic programming. For each problem, follow the design steps of the first lesson the solutions are grouped at the end of the page.","permalink":"/concepts/dynamic-programming/exercises"},{"id":"greedy-algorithms/exercises","title":"Exercises: Greedy Algorithms","description":"These exercises review the two lessons on greedy algorithms. Most of them follow the same pattern the solutions are grouped at the end of the page.","permalink":"/concepts/greedy-algorithms/exercises"},{"id":"mathematical-background/exercises","title":"Exercises: Mathematical Background","description":"These exercises practice the tools of the two lessons of the appendix the solutions are grouped at the end of the page.","permalink":"/concepts/mathematical-background/exercises"},{"id":"parallel-algorithms/exercises","title":"Exercises: Parallel Algorithms","description":"These exercises review the three lessons of the chapter the solutions are grouped at the end of the page.","permalink":"/concepts/parallel-algorithms/exercises"},{"id":"principles-of-algorithmics/exercises","title":"Exercises: Principles of Algorithmics","description":"These exercises review the whole chapter, from the definition of an algorithm to searching. They are ordered by lesson, and within each group from easier to harder. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/principles-of-algorithmics/exercises"},{"id":"sorting/exercises","title":"Exercises: Sorting","description":"These exercises review the whole sorting chapter. They use the versions of the algorithms given in the lessons (for example, the bubble sort of the lesson moves the smallest elements to the left, scanning from right to left). Try each exercise before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/sorting/exercises"}],"unlisted":false}}')}}]);